public static void main(Args        _args)
{
    SalesQuotationTable                     salesQuotationTable;
    AVASalesCreateQuotationBVRequest        salesCreateQuotationBVRequest = new AVASalesCreateQuotationBVRequest(salesQuotationTable,QuotationType::Sales);
    KCS_KBVRequestTable                     requestTable = _args.record();
    salesCreateQuotationBVRequest.parmKBVRequestTable(requestTable);
    salesCreateQuotationBVRequest.create();
}

public KCS_KBVRequestTable      parmKBVRequestTable(KCS_KBVRequestTable        _KBVrequestTable = KBVrequestTable)
{
    KBVrequestTable = _KBVrequestTable;
    return KBVrequestTable;
}

public boolean create()
{
    Args                    args = new Args();

    args.name(this.createForm());
    args.caller(this);
    args.parmEnumeration(QuotationType::Sales);
    args.record(KBVrequestTable);

    FormRun salesCreateQuotation = classfactory.formRunClass(args);
    salesCreateQuotation.init();
    salesCreateQuotation.run();
    salesCreateQuotation.wait();
    return true;
}
